import sys
from fractions import Fraction

def generate_beautiful_integers(k, max_value):
    beautiful = []
    queue = [k]

    while queue:
        num = queue.pop(0)
        if num > max_value:
            continue
        beautiful.append(num)

        next1 = num * 10
        next2 = num * 10 + k

        if next1 <= max_value:
            queue.append(next1)
        if next2 <= max_value:
            queue.append(next2)

    return sorted(beautiful, reverse=True)

def generate_beautiful_fractions(k, max_period=10):
    fractions = []

    for period_len in range(1, max_period + 1):
        denominator = 10**period_len - 1

        # Генерируем все возможные периоды из 0 и k
        for length in range(1, period_len + 1):
            for i in range(1 << length):
                numerator = 0
                for j in range(length):
                    if (i >> j) & 1:
                        numerator = numerator * 10 + k

                if numerator > 0 and numerator < denominator:
                    frac = Fraction(numerator, denominator)
                    if frac not in [f[0] for f in fractions]:
                        # Создаем красивое представление дроби
                        period_str = ""
                        for j in range(length):
                            if (i >> j) & 1:
                                period_str = str(k) + period_str
                            else:
                                period_str = "0" + period_str
                        decimal_repr = f"0.({period_str})"
                        fractions.append((frac, decimal_repr))

    # Сортируем по убыванию
    fractions.sort(key=lambda x: x[0], reverse=True)
    return fractions

def find_min_decomposition(n, k):
    # Генерируем красивые целые числа
    beautiful_ints = generate_beautiful_integers(k, n)

    # Жадный алгоритм для целых чисел
    def greedy_decompose(remainder):
        result = []
        for num in beautiful_ints:
            count = remainder // num
            if count > 0:
                result.extend([str(num)] * count)
                remainder -= num * count
            if remainder == 0:
                return result
        return None

    # Пробуем разложить только целыми числами
    result = greedy_decompose(n)
    if result:
        return result

    # Если не получилось, используем дроби
    beautiful_fractions = generate_beautiful_fractions(k)

    # Жадный алгоритм для дробей
    result = []
    remainder = Fraction(n, 1)

    for frac, decimal_str in beautiful_fractions:
        while remainder >= frac:
            result.append(decimal_str)
            remainder -= frac
            if remainder == 0:
                return result

    return result

def main():
    n, k = map(int, sys.stdin.readline().strip().split())

    result = find_min_decomposition(n, k)

    with open("OUTPUT.TXT", "w") as f:
        f.write(f"{n}=" + "+".join(result))

if __name__ == "__main__":
    main()

