    L = int(data[3])
    N = int(data[4])
    X = [int(data[5 + i]) for i in range(N)]

    if L <= U:
        print(0)
        return

    max_positions = U - H + 1
    intersections = [0] * max_positions

    for line_coord in X:
        if line_coord >= L:
            break

        start_scroll = max(0, line_coord - U + 1)
        end_scroll = min(L - U, line_coord)

        if start_scroll > end_scroll:
            continue

        start_scroll = ((start_scroll + T - 1) // T) * T
        end_scroll = (end_scroll // T) * T

        if start_scroll > end_scroll:
            continue

        for scroll in range(start_scroll, end_scroll + 1, T):
            line_screen_pos = line_coord - scroll
            if 0 <= line_screen_pos < U:
                for cursor_pos in range(max(0, line_screen_pos - H + 1), min(max_positions, line_screen_pos + 1)):
                    intersections[cursor_pos] += 1

    print(min(intersections))

