import sys
import math
from decimal import Decimal, getcontext

getcontext().prec = 50

def point_distance_to_line(px, py, x1, y1, x2, y2):
    A = x2 - x1
    B = y2 - y1
    C = y1 * x2 - x1 * y2
    return abs(A * py - B * px + C) / math.sqrt(A*A + B*B)

def segment_distance_to_circle(x1, y1, x2, y2, cx, cy, r):
    dx = x2 - x1
    dy = y2 - y1
    fx = x1 - cx
    fy = y1 - cy

    a = dx*dx + dy*dy
    b = 2 * (fx*dx + fy*dy)
    c = fx*fx + fy*fy - r*r

    discriminant = b*b - 4*a*c

    if discriminant < 0:
        return float('inf')

    sqrt_disc = math.sqrt(discriminant)
    t1 = (-b + sqrt_disc) / (2*a)
    t2 = (-b - sqrt_disc) / (2*a)

    if 0 <= t1 <= 1 or 0 <= t2 <= 1:
        return 0

    d1 = math.sqrt(fx*fx + fy*fy)
    fx2 = x2 - cx
    fy2 = y2 - cy
    d2 = math.sqrt(fx2*fx2 + fy2*fy2)

    return min(d1, d2)

def has_clearing(trees):
    n = len(trees)
    if n <= 1:
        return False

    points = []
    for x, y, r in trees:
        points.append((x, y, r))

    for i in range(n):
        for j in range(i+1, n):
            x1, y1, r1 = points[i]
            x2, y2, r2 = points[j]

            valid = True
            for k in range(n):
                if k != i and k != j:
                    dist = segment_distance_to_circle(x1, y1, x2, y2, points[k][0], points[k][1], points[k][2])
                    if dist <= 1e-9:
                        valid = False
                        break

            if valid:
                return True

    return False

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    trees = []
    idx = 1
    for _ in range(n):
        x = float(data[idx]); y = float(data[idx+1]); r = float(data[idx+2])
        idx += 3
        trees.append((x, y, r))

    if has_clearing(trees):
        print("NO")
    else:
        print("YES")

if __name__ == "__main__":
    main()

