        return

    def count_with_prefix(prefix_len, prefix_digits):
        count = 0
        for num in numbers:
            match = True
            for i in range(prefix_len):
                if num[i] != prefix_digits[i]:
                    match = False
                    break
            if match:
                count += 1
        return count

    min_cost = float('inf')

    for num in numbers:
        total_cost = 0
