import re
import math
import sys

def tokenize(expr):
    token_pattern = re.compile(r'(\d+\.\d+|\d+|[a-zA-Z_][a-zA-Z0-9_]*|[+\-*/()]|\s+)')
    tokens = []
    for match in token_pattern.finditer(expr):
        token = match.group().strip()
        if token:
            tokens.append(token)
    return tokens

def parse_expression(tokens, pos):
    result = parse_term(tokens, pos)
    while pos[0] < len(tokens) and tokens[pos[0]] in ['+', '-']:
        op = tokens[pos[0]]
        pos[0] += 1
        right = parse_term(tokens, pos)
        if op == '+':
            result += right
        else:
            result -= right
    return result

def parse_term(tokens, pos):
    result = parse_factor(tokens, pos)
    while pos[0] < len(tokens) and tokens[pos[0]] in ['*', '/']:
        op = tokens[pos[0]]
        pos[0] += 1
        right = parse_factor(tokens, pos)
        if op == '*':
            result *= right
        else:
            result /= right
    return result

def parse_factor(tokens, pos):
    if pos[0] >= len(tokens):
        raise ValueError("Unexpected end of expression")

    token = tokens[pos[0]]

    if token == '(':
        pos[0] += 1
        result = parse_expression(tokens, pos)
        if pos[0] >= len(tokens) or tokens[pos[0]] != ')':
            raise ValueError("Missing closing parenthesis")
        pos[0] += 1
        return result
    elif token in ['cos', 'sin']:
        func_name = token
        pos[0] += 1
        if pos[0] >= len(tokens) or tokens[pos[0]] != '(':
            raise ValueError(f"Missing opening parenthesis after {func_name}")
        pos[0] += 1
        arg = parse_expression(tokens, pos)
        if pos[0] >= len(tokens) or tokens[pos[0]] != ')':
            raise ValueError(f"Missing closing parenthesis after {func_name} argument")
        pos[0] += 1
        if func_name == 'cos':
            return math.cos(arg)
        else:
            return math.sin(arg)
    elif token.replace('.', '').isdigit():
        pos[0] += 1
        return float(token)
    elif token == '-':
        pos[0] += 1
        return -parse_factor(tokens, pos)
    else:
        raise ValueError(f"Unexpected token: {token}")

try:
    with open('INPUT.TXT', 'r') as f:
        expression = f.read().strip()

    tokens = tokenize(expression)
    pos = [0]
    result = parse_expression(tokens, pos)

    if pos[0] != len(tokens):
        raise ValueError("Invalid syntax")

    with open('OUTPUT.TXT', 'w') as f:
        f.write(f"{result:.3f}\n")

except Exception as e:
    with open('OUTPUT.TXT', 'w') as f:
        f.write("Error\n")

