        dp[0][0] = 0

        for i in range(1, N + 1):
            for k in range(K + 1):
                if i == 1:
                    for digit in range(1, 10):
                        if k >= segments[digit] and dp[i-1][k - segments[digit]] != INF:
                            if dp[i][k] > dp[i-1][k - segments[digit]] * 10 + digit:
                                dp[i][k] = dp[i-1][k - segments[digit]] * 10 + digit
                                choice[i][k] = digit
                else:
                    for digit in range(10):
