                                dp[i][k] = dp[i-1][k - segments[digit]] * 10 + digit
                                choice[i][k] = digit

        if dp[N][K] == INF:
            return "NO SOLUTION"

        result = []
        k = K
        for i in range(N, 0, -1):
            digit = choice[i][k]
            result.append(str(digit))
            k -= segments[digit]

