import math
import sys

def solve():
    input_file = open('INPUT.TXT', 'r')
    output_file = open('OUTPUT.TXT', 'w')

    n = int(input_file.readline().strip())
    points = []
    for _ in range(n):
        x, y = map(int, input_file.readline().strip().split())
        points.append((x, y))

    input_file.close()

    # Предварительно вычислим все расстояния
    distances = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = points[i][0] - points[j][0]
            dy = points[i][1] - points[j][1]
            dist = math.sqrt(dx * dx + dy * dy)
            distances.append(dist)

    distances.sort()

    def can_color_with_radius(r):
        # Построим граф конфликтов только для рёбер с длиной < 2*r
        adj = [[] for _ in range(n)]

        # Используем предварительно вычисленные расстояния
        for i in range(n):
            for j in range(i + 1, n):
                dx = points[i][0] - points[j][0]
                dy = points[i][1] - points[j][1]
                dist_sq = dx * dx + dy * dy
                if dist_sq < 4 * r * r - 1e-12:
                    adj[i].append(j)
                    adj[j].append(i)

        # Проверим, является ли граф двудольным
        color = [-1] * n

        def dfs(v, c):
            color[v] = c
            for u in adj[v]:
                if color[u] == -1:
                    if not dfs(u, 1 - c):
                        return False
                elif color[u] == c:
                    return False
            return True

        for i in range(n):
            if color[i] == -1:
                if not dfs(i, 0):
                    return None

        return [1 if color[i] == 0 else 2 for i in range(n)]

    # Бинарный поиск по ответу
    left = 0.0
    right = distances[-1] / 2 + 1.0

    for _ in range(80):
        mid = (left + right) / 2
        result = can_color_with_radius(mid)
        if result is not None:
            left = mid
        else:
            right = mid

    final_r = left
    final_colors = can_color_with_radius(final_r)

    output_file.write(f"{final_r}\n")
    output_file.write(" ".join(map(str, final_colors)) + "\n")
    output_file.close()

if __name__ == "__main__":
    solve()

