import sys
import math

def compare_towers(tower1, tower2):
    # Сравниваем две башни, возвращаем -1 если tower1 < tower2, 1 если tower1 > tower2, 0 если равны
    # Используем логарифмы для избежания переполнения

    # Сравниваем сначала по длине
    if len(tower1) != len(tower2):
        return len(tower1) - len(tower2)

    # Если длины равны, сравниваем по элементам
    for i in range(len(tower1)):
        if tower1[i] != tower2[i]:
            # Используем логарифмы для сравнения башен одинаковой длины
            log1 = math.log(tower1[-1])
            log2 = math.log(tower2[-1])

            for j in range(len(tower1) - 2, -1, -1):
                log1 = tower1[j] * log1
                log2 = tower2[j] * log2

                # Если одно значение намного больше другого, можно сделать вывод
                if log1 > 1000 and log2 < 500:
                    return 1
