import sys

def find(parent, x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x

def union(parent, rank, x, y):
    root_x = find(parent, x)
    root_y = find(parent, y)
    if root_x == root_y:
        return False
    if rank[root_x] < rank[root_y]:
        parent[root_x] = root_y
    elif rank[root_x] > rank[root_y]:
        parent[root_y] = root_x
    else:
        parent[root_y] = root_x
        rank[root_x] += 1
    return True

def kruskal(n, edges, exclude_edge=None):
    parent = list(range(n))
    rank = [0] * n
    selected_edges = []
    bad_count = 0

    for u, v, status, edge_idx in edges:
        if edge_idx == exclude_edge:
            continue
        if union(parent, rank, u, v):
            selected_edges.append(edge_idx)
            if status == 2:
                bad_count += 1

    # Check if we have spanning tree
    components = set()
    for i in range(n):
        components.add(find(parent, i))

    if len(components) == 1 and len(selected_edges) == n - 1:
        return selected_edges, bad_count
    return None, None

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        print(-1)
        return

    n, m = int(input_data[0]), int(input_data[1])
    edges = []
    good_edges = []
    bad_edges = []

    idx = 2
    for i in range(m):
        u = int(input_data[idx]) - 1
        v = int(input_data[idx + 1]) - 1
        status = int(input_data[idx + 2])
        idx += 3
        edges.append((u, v, status, i + 1))
        if status == 1:
            good_edges.append((u, v, status, i + 1))
        else:
            bad_edges.append((u, v, status, i + 1))

    # Sort edges by status (good first) then by index
    edges.sort(key=lambda x: (x[2], x[3]))

    # Try to find MST with even number of bad edges
    # First try standard Kruskal
    selected_edges, bad_count = kruskal(n, edges)

    if selected_edges is not None:
        if bad_count % 2 == 0:
            print('\n'.join(map(str, sorted(selected_edges))))
            return

    # If we have odd number of bad edges, try to fix it
    if selected_edges is not None and bad_count % 2 == 1:
        # Find a bad edge in MST and try to replace it
        selected_set = set(selected_edges)
        bad_in_mst = []
        good_not_in_mst = []

        for u, v, status, edge_idx in edges:
            if status == 2 and edge_idx in selected_set:
                bad_in_mst.append((u, v, status, edge_idx))
            elif status == 1 and edge_idx not in selected_set:
                good_not_in_mst.append((u, v, status, edge_idx))

        # Try replacing each bad edge in MST with each good edge not in MST
        for bad_edge in bad_in_mst:
            for good_edge in good_not_in_mst:
                # Remove bad edge and add good edge
                temp_edges = []
                for e in edges:
                    if e[3] != bad_edge[3]:
                        temp_edges.append(e)
                temp_edges.append(good_edge)
                temp_edges.sort(key=lambda x: (x[2], x[3]))

                new_selected, new_bad_count = kruskal(n, temp_edges)
                if new_selected is not None and new_bad_count % 2 == 0:
                    print('\n'.join(map(str, sorted(new_selected))))
                    return

    # If no solution found, try building MST with exactly 2 bad edges
    if len(bad_edges) >= 2:
        # First add 2 bad edges, then run Kruskal
        for i in range(len(bad_edges)):
            for j in range(i + 1, len(bad_edges)):
                temp_edges = [bad_edges[i], bad_edges[j]] + good_edges
                temp_edges.sort(key=lambda x: (x[2], x[3]))

                selected, bad_count = kruskal(n, temp_edges)
                if selected is not None and bad_count % 2 == 0:
                    print('\n'.join(map(str, sorted(selected))))
                    return

    print(-1)

if __name__ == "__main__":
