import sys

def next_partition(n, parts):
    parts = [sorted(part) for part in parts]
    parts.sort()

    max_singleton = None
    for i in range(n, 0, -1):
        if [i] in parts:
            max_singleton = i
            break

    if max_singleton is None:
        return [[i] for i in range(1, n + 1)]

    max_non_singleton = None
    for part in parts:
        if len(part) > 1:
            max_non_singleton = max(max_non_singleton or 0, max(part))

    if max_non_singleton is None or max_singleton > max_non_singleton:
        for i in range(len(parts) - 1, -1, -1):
            if parts[i][0] < max_singleton:
                parts[i].append(max_singleton)
                parts[i].sort()
                for j in range(len(parts) - 1, i, -1):
                    if parts[j] == [max_singleton]:
                        parts.pop(j)
                        break
                parts.sort()
                return parts

    for i in range(len(parts) - 1, -1, -1):
        if len(parts[i]) > 1 and max(parts[i]) < max_singleton:
            idx = parts[i].index(max_singleton - 1)
            parts[i] = parts[i][:idx] + [max_singleton] + parts[i][idx+1:]
            for j in range(len(parts) - 1, -1, -1):
                if parts[j] == [max_singleton - 1]:
                    parts.pop(j)
                    break
            parts.sort()
            return parts

    return [[i] for i in range(1, n + 1)]

def main():
