    results = []
    i = 0

    while i < len(data):
        line = data[i].strip()
        if not line:
            i += 1
            continue

        n, k = map(int, line.split())
        if n == 0 and k == 0:
            break

        parts = []
        for j in range(k):
            i += 1
            if i >= len(data):
                break
            part = list(map(int, data[i].strip().split()))
            parts.append(part)

        result = next_partition(n, parts)
        results.append(f"{n} {len(result)}")
        for part in result:
            results.append(" ".join(map(str, sorted(part))))

        i += 1

    print("\n".join(results))

if __name__ == "__main__":
