import sys
from functools import lru_cache

def solve():
    data = sys.stdin.read().splitlines()
    n, r = map(int, data[0].split())
    word = data[1].strip()
    q = list(map(float, data[2].split()))

    unique_letters = set(word)
    total_unique = len(unique_letters)
    total_length = len(word)

    @lru_cache(maxsize=None)
    def dp(mask, player_idx):
        revealed_count = bin(mask).count('1')

        if revealed_count == total_length:
            return 1.0 if (player_idx - 1) % n == r - 1 else 0.0

        unknown_letters = 0
        letter_positions = {}

        for i, char in enumerate(word):
            if not (mask & (1 << i)):
                if char not in letter_positions:
                    unknown_letters += 1
                    letter_positions[char] = []
                letter_positions[char].append(i)

        if unknown_letters == 0:
            return 1.0 if (player_idx - 1) % n == r - 1 else 0.0

        qt = q[player_idx - 1]
        i = revealed_count
        j = unknown_letters
        k = total_length - revealed_count

        if j == 0:
            base_prob = 1.0
        else:
            base_prob = qt ** (i + 1)

        if j - 1 <= 0:
            second_factor = 1.0
        else:
            second_factor = (1 - qt) ** (j - 1)

        if k <= 0:
            third_factor = 1.0
        else:
            third_factor = qt ** k

        prob_correct = 1 - base_prob * second_factor * third_factor

        prob_wrong = 1 - prob_correct

        next_player = (player_idx % n) + 1
        result = prob_wrong * dp(mask, next_player)

        if prob_correct > 0 and unknown_letters > 0:
            prob_per_letter = prob_correct / unknown_letters

            for positions in letter_positions.values():
                new_mask = mask
                for pos in positions:
                    new_mask |= (1 << pos)

                if bin(new_mask).count('1') < total_length:
                    result += prob_per_letter * dp(new_mask, player_idx)
                else:
                    result += prob_per_letter * (1.0 if player_idx == r else 0.0)

        return result

    result = dp(0, 1)
    print(f"{result:.10f}")

