    def count_young_diagrams(partition):
        partition = tuple(partition)
        if not partition:
            return 1

        total = 1
        for i in range(len(partition)):
            if partition[i] > 0:
                new_partition = list(partition)
                new_partition[i] -= 1
                if i + 1 < len(partition) and new_partition[i] < new_partition[i + 1]:
                    new_partition[i], new_partition[i + 1] = new_partition[i + 1], new_partition[i]
