import sys

def solve():
    S = sys.stdin.readline().strip()
    n = len(S)

    # Precompute LPS (Longest Prefix Suffix) for all prefixes
    def compute_lps(pattern):
        m = len(pattern)
        lps = [0] * m
        length = 0
        i = 1
        while i < m:
            if pattern[i] == pattern[length]:
                length += 1
                lps[i] = length
                i += 1
            else:
                if length != 0:
                    length = lps[length - 1]
                else:
                    lps[i] = 0
                    i += 1
        return lps

    # Check if string is a repetition
    def is_repetition(s):
        lps = compute_lps(s)
        m = len(s)
        if lps[m - 1] > 0 and m % (m - lps[m - 1]) == 0:
            period = m - lps[m - 1]
            if m // period > 1:
                return s[:period], m // period
        return None

    # Precompute repetitions for all substrings
    repetitions = {}
    for i in range(n):
        for j in range(i + 2, n + 1):  # Only check substrings of length >= 2
            substr = S[i:j]
            rep_info = is_repetition(substr)
            if rep_info:
                repetitions[(i, j)] = rep_info

    # DP: dp[i] = min weight to decompose S[0:i]
    dp = [float('inf')] * (n + 1)
    parent = [None] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        # Try all possible last segments S[j:i]
        for j in range(i):
            if dp[j] == float('inf'):
                continue

            if (j, i) in repetitions:
                base, power = repetitions[(j, i)]
                new_weight = dp[j] + len(base)
                if new_weight < dp[i]:
                    dp[i] = new_weight
                    parent[i] = (j, base, power)
            else:
                # Single occurrence
                new_weight = dp[j] + (i - j)
                if new_weight < dp[i]:
                    dp[i] = new_weight
                    parent[i] = (j, S[j:i], 1)

    # Reconstruct the decomposition
    result = []
    pos = n
    while pos > 0:
        prev, base, power = parent[pos]
        result.append((base, power))
        pos = prev

    result.reverse()

    # Output
    with open('OUTPUT.TXT', 'w') as f:
        f.write(str(dp[n]) + '\n')
        for base, power in result:
            f.write(f"{base} {power}\n")

if __name__ == "__main__":
    solve()

