import sys
import math

def orientation(ax, ay, bx, by, cx, cy):
    return (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)

def on_segment(ax, ay, bx, by, cx, cy):
    return min(ax, bx) <= cx <= max(ax, bx) and min(ay, by) <= cy <= max(ay, by)

def segments_intersect(x1, y1, x2, y2, x3, y3, x4, y4):
    o1 = orientation(x1, y1, x2, y2, x3, y3)
    o2 = orientation(x1, y1, x2, y2, x4, y4)
    o3 = orientation(x3, y3, x4, y4, x1, y1)
    o4 = orientation(x3, y3, x4, y4, x2, y2)

    if o1 == 0 and on_segment(x1, y1, x2, y2, x3, y3):
        return True
    if o2 == 0 and on_segment(x1, y1, x2, y2, x4, y4):
        return True
    if o3 == 0 and on_segment(x3, y3, x4, y4, x1, y1):
        return True
    if o4 == 0 and on_segment(x3, y3, x4, y4, x2, y2):
        return True

    return o1 * o2 < 0 and o3 * o4 < 0

def point_to_segment_distance(px, py, x1, y1, x2, y2):
    dx = x2 - x1
    dy = y2 - y1

    if abs(dx) < 1e-12 and abs(dy) < 1e-12:
        return math.hypot(px - x1, py - y1)

    t = ((px - x1) * dx + (py - y1) * dy) / (dx * dx + dy * dy)

    if t < 0:
        return math.hypot(px - x1, py - y1)
    elif t > 1:
        return math.hypot(px - x2, py - y2)
    else:
        proj_x = x1 + t * dx
        proj_y = y1 + t * dy
        return math.hypot(px - proj_x, py - proj_y)

def segments_distance(x1, y1, x2, y2, x3, y3, x4, y4):
    if segments_intersect(x1, y1, x2, y2, x3, y3, x4, y4):
        return 0.0

    d1 = point_to_segment_distance(x3, y3, x1, y1, x2, y2)
    d2 = point_to_segment_distance(x4, y4, x1, y1, x2, y2)
    d3 = point_to_segment_distance(x1, y1, x3, y3, x4, y4)
    d4 = point_to_segment_distance(x2, y2, x3, y3, x4, y4)

    return min(d1, d2, d3, d4)

def find_intersection_time(x1, y1, x2, y2, x3, y3, x4, y4, v1x, v1y, v2x, v2y):
    # Проверяем пересечение в начальный момент
    if segments_intersect(x1, y1, x2, y2, x3, y3, x4, y4):
        return 0.0

    # Относительная скорость второго отрезка относительно первого
    rx = v2x - v1x
    ry = v2y - v1y

    # Если отрезки не двигаются относительно друг друга
    if abs(rx) < 1e-12 and abs(ry) < 1e-12:
        return -1

    # Бинарный поиск по времени
    left, right = 0.0, 1e9
    eps = 1e-9
    max_iter = 100

    for _ in range(max_iter):
        mid = (left + right) / 2

        # Позиции отрезков через время mid
        nx1 = x1 + v1x * mid
        ny1 = y1 + v1y * mid
        nx2 = x2 + v1x * mid
        ny2 = y2 + v1y * mid
        nx3 = x3 + v2x * mid
        ny3 = y3 + v2y * mid
        nx4 = x4 + v2x * mid
        ny4 = y4 + v2y * mid

        if segments_intersect(nx1, ny1, nx2, ny2, nx3, ny3, nx4, ny4):
            right = mid
        else:
            left = mid

    final_time = (left + right) / 2

    # Проверяем, действительно ли отрезки соприкоснутся
    nx1 = x1 + v1x * final_time
    ny1 = y1 + v1y * final_time
    nx2 = x2 + v1x * final_time
    ny2 = y2 + v1y * final_time
    nx3 = x3 + v2x * final_time
    ny3 = y3 + v2y * final_time
    nx4 = x4 + v2x * final_time
    ny4 = y4 + v2y * final_time

    if segments_intersect(nx1, ny1, nx2, ny2, nx3, ny3, nx4, ny4):
        return final_time
    else:
        return -1

def main():
    data = []
    for line in sys.stdin:
        data.extend(map(float, line.split()))
        if len(data) >= 12:
            break

    x1, y1, x2, y2, x3, y3, x4, y4, v1x, v1y, v2x, v2y = data[:12]

