from itertools import combinations

def solve():
    with open('INPUT.TXT', 'r') as f:
        input_data = f.read().strip().split()

    n, m = int(input_data[0]), int(input_data[1])
    edges = []
    idx = 2
    for _ in range(m):
        a, b = int(input_data[idx]) - 1, int(input_data[idx + 1]) - 1
        idx += 2
        edges.append((a, b))

    def find(parent, x):
        if parent[x] != x:
            parent[x] = find(parent, parent[x])
        return parent[x]

    def union(parent, rank, x, y):
        root_x = find(parent, x)
        root_y = find(parent, y)
        if root_x != root_y:
            if rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            elif rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            else:
                parent[root_y] = root_x
                rank[root_x] += 1
            return True
        return False

    def is_spanning_tree(edge_set):
        if len(edge_set) != n - 1:
            return False
        parent = [i for i in range(n)]
        rank = [0] * n
        components = n
        for a, b in edge_set:
            if union(parent, rank, a, b):
                components -= 1
        return components == 1

    count = 0
    for combo in combinations(edges, n - 1):
        if is_spanning_tree(combo):
            count += 1

    with open('OUTPUT.TXT', 'w') as f:
        f.write(str(count))

if __name__ == "__main__":
