        n, m = map(int, f.readline().split())
        grid = [list(line.strip()) for line in f.readlines()]

    rows = n
    cols = m
    total = 0

    def can_place(x, y, size):
        if x + size > rows or y + size > cols:
            return False
        for i in range(x, x + size):
            for j in range(y, y + size):
                if grid[i][j] != '.':
                    return False
        return True

    def place_tile(x, y, size, mark):
        for i in range(x, x + size):
            for j in range(y, y + size):
                grid[i][j] = mark

    def backtrack(x, y):
        nonlocal total
        if x == rows:
            total += 1
            return

        if y == cols:
            backtrack(x + 1, 0)
            return

        if grid[x][y] != '.':
            backtrack(x, y + 1)
            return

        max_size = 1
        while can_place(x, y, max_size + 1):
            max_size += 1

        for size in range(1, max_size + 1):
            place_tile(x, y, size, 'X')
            backtrack(x, y + size)
            place_tile(x, y, size, '.')

    backtrack(0, 0)

    with open('OUTPUT.TXT', 'w') as f:
