        if len(parts) > 1:
            # Последняя часть должна быть доменом из 2-3 букв
            tld = parts[-1]
            if len(tld) < 2 or len(tld) > 3:
                return False
            if not re.match(r'^[a-zA-Z]+$', tld):
                return False

            # Все остальные части должны быть валидными словами
            for part in parts[:-1]:
                if not part or not is_valid_word(part):
                    return False
            return True

        # Если нет точек, это просто имя компьютера
