            remaining = protocol_match.group(2)
        else:
            # Протокол может быть опущен, используем http по умолчанию
            remaining = url

        if not remaining:
            return False

        # Разделяем на хост/порт и путь
        if '/' in remaining:
            host_port_str, path_str = remaining.split('/', 1)
            path = '/' + path_str
        else:
