def construct_fold_sequence(n, s):
    length = (1 << n) - 1
    if len(s) != length:
        return "NO"

    result = []

    def solve(level, start, end, direction):
        if level == 0:
            return True

        mid = (start + end) // 2
        left_start = start
        left_end = mid - 1
        right_start = mid + 1
        right_end = end

        if direction == 'forward':
            if s[mid] == 'K':
                result.append('P')
                return solve(level - 1, left_start, left_end, 'forward') and \
                       solve(level - 1, right_start, right_end, 'reverse')
            else:
                result.append('Z')
                return solve(level - 1, left_start, left_end, 'forward') and \
                       solve(level - 1, right_start, right_end, 'reverse')
        else:
            if s[mid] == 'O':
                result.append('P')
                return solve(level - 1, left_start, left_end, 'reverse') and \
                       solve(level - 1, right_start, right_end, 'forward')
            else:
                result.append('Z')
                return solve(level - 1, left_start, left_end, 'reverse') and \
                       solve(level - 1, right_start, right_end, 'forward')

    if solve(n, 0, length - 1, 'forward'):
        return ''.join(result)
    else:
        return "NO"

