def main():
    tw, th, w, h = map(int, sys.stdin.readline().split())

    def can_tile():
        if (w % tw == 0 and h % th == 0) or (w % th == 0 and h % tw == 0):
            return True

        def can_fill_with_gcd():
            total_area = w * h
            tile_area = tw * th
            if total_area % tile_area != 0:
                return False

            g = math.gcd(tw, th)
            if w % g != 0 or h % g != 0:
                return False

            max_dim = max(tw, th)
            min_dim = min(tw, th)

            if w % max_dim == 0 or h % max_dim == 0:
                return True

            if (w % min_dim == 0 and h % max_dim == 0) or (h % min_dim == 0 and w % max_dim == 0):
                return True

            w_mod = w % max_dim
            h_mod = h % max_dim

            if (w_mod % min_dim == 0 and h_mod % min_dim == 0):
                return True

            return False

        return can_fill_with_gcd()

    result = can_tile()
    print("YES" if result else "NO")

