            return memo[rows_tuple]

        if len(rows) == 0 or is_irreducible(rows):
            result = {rows_tuple}
            memo[rows_tuple] = result
            return result

        result = set()

        # Try removing entire last row if possible
        if len(rows) >= 2:
            new_rows = rows[:-1]
            result.update(get_irreducible_diagrams(new_rows))

        # Try removing pairs from adjacent rows
        for i in range(len(rows) - 1):
            # Check if we can remove from rows i and i+1
