import sys

def encode_number(num):
    # Преобразуем число в 8 байт в формате дополнения до двух (big-endian)
    bytes_val = num.to_bytes(8, byteorder='big', signed=True)
    first_byte = bytes_val[0]

    # Проверяем все возможные значения q от 0 до 8
    for q in range(8):
        # Определяем позицию бита расширения
        if q == 7:
            ext_bit_pos = 7
            ext_byte = bytes_val[1]
        else:
            ext_bit_pos = 7 - (q + 1)
            ext_byte = first_byte

        ext_bit = (ext_byte >> ext_bit_pos) & 1

        # Проверяем, можно ли использовать данный q
        can_encode = True

        if ext_bit == 0:
            # Метод A: обнуляем старшие q бит
            # Проверяем, что число неотрицательное
            if num < 0:
                can_encode = False
            else:
                # Проверяем, что после обнуления старших q бит получим исходное число
                # Обнуляем старшие q бит в первом байте
                mask = (0xFF >> (q + 1)) << (7 - q)
                test_first_byte = first_byte & ~mask
                test_bytes = bytearray([test_first_byte] + list(bytes_val[1:]))
                test_num = int.from_bytes(test_bytes, byteorder='big', signed=True)
                if test_num != num:
                    can_encode = False
        else:
            # Метод B: устанавливаем (q+1)-й бит в 1 и дополняем 0xff
            # Проверяем, что число отрицательное
            if num >= 0:
                can_encode = False
            else:
                # Проверяем, что после установки бита получим исходное число
                bit_pos = 7 - (q + 1)
                test_first_byte = first_byte | (1 << bit_pos)
                test_bytes = bytearray([test_first_byte] + list(bytes_val[1:]))
                test_num = int.from_bytes(test_bytes, byteorder='big', signed=True)
                if test_num != num:
                    can_encode = False

        if can_encode:
            # Кодируем с этим q
            result = bytearray(q + 1)

            # Устанавливаем q единиц в начале
            for i in range(q):
                result[0] |= (1 << (7 - i))

            # Добавляем нужные байты из исходного числа
            if ext_bit == 0:
                # Метод A: обнуляем старшие q бит
                mask = (0xFF >> (q + 1)) << (7 - q)
                result[0] = first_byte & ~mask
            else:
                # Метод B: устанавливаем (q+1)-й бит
                bit_pos = 7 - (q + 1)
                result[0] = first_byte | (1 << bit_pos)

            # Копируем оставшиеся байты
            for i in range(1, q + 1):
                result[i] = bytes_val[i]

            return result.hex()

    # Если не получилось закодировать коротко, используем 9 байт
    return '80' + bytes_val.hex()

def main():
    data = sys.stdin.read().strip()
    if not data:
        return

    lines = data.split('\n')
    n = int(lines[0])

    for i in range(1, n + 1):
        num = int(lines[i].strip())
        print(encode_number(num))

if __name__ == "__main__":
    main()
